<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h4 fw-bold mb-0">OPS Finance <?= !empty($history) ? 'Project History' : 'Incoming Projects' ?></h1><a class="btn btn-outline-secondary btn-sm" href="<?= url('/ops-finance/dashboard') ?>">Dashboard</a></div>
<form method="get" class="bms-card p-3 mb-3"><div class="row g-2"><div class="col-md-3"><input name="q" value="<?= e($filters['q']) ?>" class="form-control form-control-sm" placeholder="Project name or reference"></div><div class="col-md-2"><select name="category" class="form-select form-select-sm"><option value="">All categories</option><option value="mrc" <?= $filters['category']==='mrc'?'selected':'' ?>>MRC</option><option value="special_project" <?= $filters['category']==='special_project'?'selected':'' ?>>Special Project</option></select></div><div class="col-md-2"><input type="date" name="date_from" value="<?= e($filters['date_from']) ?>" class="form-control form-control-sm"></div><div class="col-md-2"><input type="date" name="date_to" value="<?= e($filters['date_to']) ?>" class="form-control form-control-sm"></div><div class="col-md-2"><button class="btn btn-primary btn-sm">Filter</button> <a class="btn btn-link btn-sm" href="<?= url('/ops-finance/projects') ?>">Clear</a></div></div></form>
<div class="bms-card p-3"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Reference</th><th>Project / Client</th><th>Category</th><th>Received</th><th>PR</th><th>Canvassing</th><th>Status</th></tr></thead><tbody><?php foreach ($queue as $p): ?><tr><td><a class="fw-semibold" href="<?= url('/ops-finance/projects/'.(int)$p['id']) ?>"><?= e($p['project_code']) ?></a></td><td><?= e($p['project_name']) ?><div class="small text-secondary"><?= e($p['client_name']) ?></div></td><td><?= e($p['category_label']) ?></td><td><?= e($p['opfin_received_at'] ?? '') ?></td><td><?= !empty($p['pr']) ? '<span class="text-success">Uploaded</span>' : '<span class="text-danger">Missing</span>' ?></td><td><?= (int)$p['canvassing_count'] ?></td><td><?= e($p['status']) ?></td></tr><?php endforeach; ?><?php if (!$queue): ?><tr><td colspan="7" class="text-center text-secondary py-5">No projects found.</td></tr><?php endif; ?></tbody></table></div></div>
